 "content": "def transform(grid):
    """Connect every marker (2) to the horizontal row containing the marker pair."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    row_markers = {}
    for r, c in points:
        row_markers.setdefault(r, []).append(c)
    trunk_row = next((r for r, cols in row_markers.items() if len(cols) >= 2), None)
    if trunk_row is None:
        return out

    left, right = min(row_markers[trunk_row]), max(row_markers[trunk_row])
    for c in range(left + 1, right):
        if out[trunk_row][c] == 0:
            out[trunk_row][c] = 3
    for r, c in points:
        if r == trunk_row:
            continue
        for rr in range(min(r, trunk_row) + 1, max(r, trunk_row)):
